import sys

def fractionToDecimal(numerator: int, denominator: int) -> str:
    if numerator == 0:
        return "0"

    result = []

    # Handle sign
    if (numerator < 0) ^ (denominator < 0):
        result.append("-")

    num = abs(numerator)
    den = abs(denominator)

    # Integer part
    result.append(str(num // den))
    remainder = num % den

    if remainder == 0:
        return "".join(result)

    result.append(".")

    # Fractional part
    seen_remainders = {}
    while remainder != 0:
        if remainder in seen_remainders:
            index = seen_remainders[remainder]
            result.insert(index, "(")
            result.append(")")
            break

        seen_remainders[remainder] = len(result)
        remainder *= 10
        digit = remainder // den
        result.append(str(digit))
        remainder %= den

    return "".join(result)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    numerator = int(input_data[0])
    denominator = int(input_data[1])

    result = fractionToDecimal(numerator, denominator)
    print(result)

if __name__ == "__main__":
    main()
